// Keep Contacts+ birthday objects intact; the native Get Contact module tries
// to coerce yearless birthdays into dates and can fail before returning a card.
function readSourceResponse(value) {
  const response=typeof value==='string'?JSON.parse(value):value;
  if(!response||typeof response!=='object'||Array.isArray(response))throw Error('Missing source response');
  if(!Object.hasOwn(response,'statusCode'))return response; // Direct test/legacy input.
  const body=typeof response.body==='string'?JSON.parse(response.body):response.body;
  if(response.statusCode!==200||!Array.isArray(body?.contacts)||body.contacts.length!==1)
    throw Error('Expected exactly one successful source contact');
  const source=body.contacts[0];
  if(!source?.contactId||typeof source.etag!=='string'||!source.etag||!source.contactData)
    throw Error('Incomplete source identity/version');
  return source;
}


// Pure, conservative Contacts+ -> vCard patching. No network or credentials.
function patchSharedFields({uid,existingVcard,contactData}) {
  const text=v=>{if(v==null)return '';if(typeof v!=='string'||/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(v))throw Error('Invalid text');return v;};
  const esc=v=>text(v).replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');
  const fold=l=>{let s='',n=0;for(const c of l){const z=Buffer.byteLength(c);if(n+z>75){s+='\r\n ';n=1;}s+=c;n+=z;}return s;};
  if(!/^[A-Za-z0-9_-]{1,128}$/.test(uid)||typeof existingVcard!=='string')throw Error('Invalid target');
  if(/\r(?!\n)|(?<!\r)\n/.test(existingVcard)||!existingVcard.endsWith('\r\n'))throw Error('Expected CRLF card');
  const records=[];
  for(const l of existingVcard.slice(0,-2).split('\r\n')){
    if(/^[ \t]/.test(l)){if(!records.length)throw Error('Invalid fold');records.at(-1).raw+='\r\n'+l;records.at(-1).line+=l.slice(1);}
    else records.push({raw:l,line:l});
  }
  const key=l=>l.split(':')[0].split(';')[0].split('.').at(-1).toUpperCase();
  const group=l=>l.split(':')[0].split(';')[0].includes('.')?l.split('.')[0]:null;
  const lines=records.map(r=>r.line);
  if(lines[0]!=='BEGIN:VCARD'||lines.at(-1)!=='END:VCARD'||lines.filter(l=>l==='BEGIN:VCARD').length!==1||lines.filter(l=>l==='END:VCARD').length!==1||lines.filter(l=>key(l)==='UID').length!==1||!lines.includes('UID:'+uid)||!lines.includes('VERSION:3.0'))throw Error('Target identity/format mismatch');
  const d=contactData;if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Missing source');
  let index=0;const occupied=new Set(records.map(r=>group(r.line)).filter(Boolean));
  const next=()=>{let g;do{g='item'+(++index);}while(occupied.has(g));occupied.add(g);return g;};
  const wanted=new Map(), managed=new Map();
  const set=(field,keys,values)=>{managed.set(field,new Set(keys));wanted.set(field,values);};
  const own=k=>Object.hasOwn(d,k)&&d[k]!=null;
  const array=k=>{if(!Array.isArray(d[k]))throw Error('Expected array '+k);return d[k];};
  const check=(x,keys)=>{if(!x||typeof x!=='object'||Object.keys(x).some(k=>!keys.includes(k)&&x[k]!=null&&x[k]!==''))throw Error('Unsupported source component');};
  function labeled(property,value,label,standard){
    if(!text(value)||/[\r\n]/.test(value))throw Error('Empty or multiline value');
    const t=text(label),upper=t.toUpperCase();
    if(!t)return [property+':'+esc(value)];
    if(standard.includes(upper))return [property+';TYPE='+upper+':'+esc(value)];
    const g=next();return [g+'.'+property+':'+esc(value),g+'.X-ABLabel:'+esc(t)];
  }
  if(own('name')){
    const n=d.name;check(n,['familyName','givenName','middleName','prefix','suffix','nickname']);
    const fn=['prefix','givenName','middleName','familyName','suffix'].map(k=>text(n[k])).filter(Boolean).join(' ');if(!fn.trim())throw Error('Empty name');
    set('name',['N','FN'],['N:'+['familyName','givenName','middleName','prefix','suffix'].map(k=>esc(n[k])).join(';'),'FN:'+esc(fn)]);
    if(Object.hasOwn(n,'nickname'))set('nickname',['NICKNAME'],n.nickname?['NICKNAME:'+esc(n.nickname)]:[]);
  }
  if(own('notes'))set('notes',['NOTE'],d.notes?['NOTE:'+esc(d.notes)]:[]);
  for(const [field,prop,labels] of [['emails','EMAIL',['HOME','WORK','INTERNET']],['phoneNumbers','TEL',['HOME','WORK','CELL','MOBILE','VOICE','FAX','PAGER','MAIN','OTHER']]])if(own(field)){
    const values=array(field).flatMap(x=>{check(x,['value','type']);return labeled(prop,x.value,x.type,labels);});set(field,[prop],values);
  }
  if(own('addresses'))set('addresses',['ADR'],array('addresses').flatMap(x=>{
    check(x,['street','extendedAddress','city','region','postalCode','country','type']);
    const value=['','',[x.street,x.extendedAddress].filter(Boolean).join('\n'),x.city,x.region,x.postalCode,x.country].map(esc).join(';');
    const t=text(x.type);if(!t||['HOME','WORK'].includes(t.toUpperCase()))return ['ADR'+(t?';TYPE='+t.toUpperCase():'')+':'+value];
    const g=next();return [g+'.ADR:'+value,g+'.X-ABLabel:'+esc(t)];
  }));
  if(own('urls')){
    const social=new Set(['linkedin','twitter','facebook','github','keybase','pinterest','youtube','instagram','flickr','myspace','skype','tiktok']);
    set('urls',['URL','X-SOCIALPROFILE'],array('urls').flatMap(x=>{
      check(x,['value','type','username','userId']);const type=text(x.type).toLowerCase();
      if(social.has(type)){
        if(!/^https?:\/\/[^\s]+$/i.test(text(x.value)))throw Error('Invalid social URL');
        const param=(key,value)=>{
          if(value==null||value==='')return '';
          // Delimiters/quoted parameters require a separate verified encoder.
          // Never allow a handle to inject another parameter or vCard line.
          if(!/^[A-Za-z0-9._~@+\-]+$/.test(text(value)))throw Error('Unsupported social parameter value');
          return ';'+key+'='+value;
        };
        return ['X-SOCIALPROFILE;TYPE='+type+param('X-USER',x.username)+param('X-USERID',x.userId)+':'+esc(x.value)];
      }
      if(x.username||x.userId)throw Error('Social profile metadata needs verified mapping');
      return labeled('URL',x.value,x.type,['HOME','WORK','HOMEPAGE','OTHER']);
    }));
  }
  if(own('organizations')){
    const orgs=array('organizations');const x=orgs[0]||{};check(x,['name','title','department','type']);
    set('organizations',['ORG','TITLE'],[...(x.name||x.department?['ORG:'+esc(x.name)+';'+esc(x.department)]:[]),...(x.title?['TITLE:'+esc(x.title)]:[])]);
  }
  if(own('ims'))set('ims',['IMPP'],array('ims').map(x=>{
    check(x,['value','type']);
    // This is the representation observed in the saved iCloud inventory.
    // Other services stay held until their URI encoding is verified.
    if(text(x.type).toLowerCase()!=='messenger')throw Error('Unsupported IM service');
    const value=text(x.value);if(!value||/[\s:]/.test(value))throw Error('Invalid IM handle');
    return 'IMPP;X-SERVICE-TYPE=Messenger:x-apple:'+esc(value);
  }));
  if(own('relatedPeople'))set('relatedPeople',['X-ABRELATEDNAMES'],array('relatedPeople').flatMap(x=>{
    check(x,['value','type']);return labeled('X-ABRELATEDNAMES',x.value,x.type,[]);
  }));
  if(own('birthday')){
    const b=d.birthday;check(b,['year','month','day']);
    const y=b.year==null?1604:b.year;
    const leap=y%4===0&&(y%100!==0||y%400===0);
    const days=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];
    if(!Number.isInteger(y)||y<1||y>9999||!Number.isInteger(b.month)||b.month<1||b.month>12||!Number.isInteger(b.day)||b.day<1||b.day>days[b.month-1])throw Error('Invalid birthday');
    set('birthday',['BDAY'],['BDAY'+(b.year==null?';X-APPLE-OMIT-YEAR=1604':'')+':'+String(y).padStart(4,'0')+'-'+String(b.month).padStart(2,'0')+'-'+String(b.day).padStart(2,'0')]);
  }
  // Metadata and alternate photos are intentionally not rendered as text fields.
  // Unknown data never disappears silently: callers must hold those records.
  const supported=new Set(['name','notes','emails','phoneNumbers','addresses','urls','organizations','birthday','photos','ims','relatedPeople']);
  for(const k of Object.keys(d))if(!supported.has(k)&&d[k]!=null&&d[k]!==''&&!(Array.isArray(d[k])&&!d[k].length))throw Error('Unsupported populated source field: '+k);
  let kept=[...records], additions=[],changedFields=[];
  for(const [field,keys] of managed){
    const selected=records.filter(r=>keys.has(key(r.line)));const groups=new Set(selected.map(r=>group(r.line)).filter(Boolean));
    const ancillary=records.filter(r=>groups.has(group(r.line))&&!keys.has(key(r.line)));
    if(ancillary.some(r=>key(r.line)!=='X-ABLABEL'))throw Error('Managed field shares group with unmanaged data');
    // Compare semantics, not group ids, folding, type-case, or preferred flags.
    const semantic=rs=>rs.filter(r=>key(r.line)!=='X-ABLABEL').map(r=>{
      const pos=r.line.indexOf(':'),head=r.line.slice(0,pos);let types=[...head.matchAll(/;type=([^;:]+)/gi)].flatMap(m=>m[1].toLowerCase().split(',')).filter(t=>!['pref','internet'].includes(t)).sort();
      const label=rs.find(x=>group(x.line)===group(r.line)&&group(r.line)&&key(x.line)==='X-ABLABEL');if(label)types=['label:'+label.line.slice(label.line.indexOf(':')+1).toLowerCase()];
      // Observed Apple service aliases. Only these two exact service names
      // are equivalent; URLs, usernames, IDs and custom labels stay exact.
      if(key(r.line)==='X-SOCIALPROFILE'&&!label)types=types.map(t=>
        t==='github.com'?'github':t==='instagram.com'?'instagram':t).sort();
      if(key(r.line)==='TEL'&&!label){
        types=[...new Set(types.map(t=>t==='mobile'?'cell':t))];
        // Apple adds VOICE to ordinary Home/Work/Mobile numbers. Preserve
        // service distinctions (fax, pager, messaging, unknown types) and
        // multi-location combinations; only a single ordinary label qualifies.
        const ordinary=types.filter(t=>t!=='voice');
        if(ordinary.length===1&&['cell','home','work'].includes(ordinary[0]))types=ordinary;
        types.sort();
      }
      const params=head.split(';').slice(1).filter(p=>!/^type=/i.test(p)&&!/^value=(date|text)$/i.test(p)).map(p=>{
        const i=p.indexOf('='),k=p.slice(0,i).toLowerCase(),v=p.slice(i+1);
        // Social IDs are opaque and case-sensitive; retain their exact value.
        return ['x-user','x-userid'].includes(k)?k+'='+v:p.toLowerCase();
      }).sort();
      let value=r.line.slice(pos+1);
      // ORG is structured: an omitted empty trailing department is equivalent
      // to an explicit empty component. Escaped literal semicolons are data.
      if(key(r.line)==='ORG')while(value.endsWith(';')){
        let slashes=0;for(let i=value.length-2;i>=0&&value[i]==='\\';i--)slashes++;
        if(slashes%2)break;
        value=value.slice(0,-1);
      }
      return key(r.line)+';'+types.join(',')+';'+params.join(';')+':'+value;
    }).sort();
    const proposed=wanted.get(field).map(line=>({line,raw:fold(line)}));
    // iCloud may return an empty FN while preserving the complete structured N.
    // Accept that representation only for one exact, unparameterized N/FN pair.
    // A real name edit must still replace both fields; never infer identity here.
    if(field==='name'&&selected.length===2&&!ancillary.length&&
       selected.some(r=>r.line==='FN:')&&
       selected.some(r=>r.line===proposed.find(p=>p.line.startsWith('N:'))?.line))continue;
    if(JSON.stringify(semantic([...selected,...ancillary]))===JSON.stringify(semantic(proposed)))continue;
    const allowed=new Set(['TYPE','VALUE',...(field==='urls'?['X-USER','X-USERID']:[]),...(field==='ims'?['X-SERVICE-TYPE']:[]),...(field==='birthday'?['X-APPLE-OMIT-YEAR']:[])]);
    if(selected.some(r=>r.line.slice(0,r.line.indexOf(':')).split(';').slice(1).some(p=>!allowed.has(p.split('=')[0].toUpperCase()))))throw Error('Unsupported target parameter');
    changedFields.push(field);kept=kept.filter(r=>!keys.has(key(r.line))&&!ancillary.includes(r));additions.push(...proposed);
  }
  if(!changedFields.length)return {vcard:existingVcard,changed:false,changedFields};
  kept.splice(kept.length-1,0,...additions);return {vcard:kept.map(r=>r.raw).join('\r\n')+'\r\n',changed:true,changedFields};
}


// Lightweight sync decisions: no contact bodies or photos are persisted here.
const crypto = require('node:crypto');
function stable(value) {
  if (value === undefined) throw new Error('Incomplete snapshot');
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  return '{' + Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',') + '}';
}
function hash(value) { return crypto.createHash('sha256').update(stable(value)).digest('hex'); }
function planFields({source,target,baseline,fields}) {
  if (!baseline) return {status:'needs_baseline',patch:{},conflicts:[]};
  const patch={}, conflicts=[];
  for (const field of fields) {
    if (!Object.hasOwn(source,field)||!Object.hasOwn(target,field)||!baseline[field])
      throw Error('Incomplete field snapshot: '+field);
    const s=hash(source[field]), t=hash(target[field]), old=baseline[field];
    if(s===t || s===old.source) continue; // Converged, or only target changed.
    if(t!==old.target) conflicts.push(field);
    else patch[field]=source[field];
  }
  // Apply nothing on a conflict: one contact is one atomic CardDAV resource.
  if(conflicts.length)return {status:'conflict',patch:{},conflicts};
  return {status:Object.keys(patch).length?'update':'unchanged',patch,conflicts};
}
function reconcile({operation,currentHash,beforeHash,expectedHash,exists,expectedUid,actualUid}) {
  if (exists && (!expectedUid || actualUid!==expectedUid)) return 'identity_conflict';
  if(operation==='delete') return exists?'hold_uncertain_delete':'verified_deleted';
  if(!['create','update'].includes(operation))throw Error('Unknown operation');
  if(exists && expectedHash && currentHash===expectedHash)return 'verified';
  // A stale/reordered source event must never force a second uncertain write.
  if(operation==='create' && !exists)return 'hold_unconfirmed_create';
  if(operation==='update' && exists && beforeHash && currentHash===beforeHash)return 'hold_unconfirmed_update';
  return 'conflict';
}
function deletionDecision({sourceMissing,mergeDisposition,mappingState}) {
  if(mappingState==='deleted')return 'already_deleted';
  if(mappingState!=='verified'||!sourceMissing)return 'hold';
  // A deletion event alone cannot tell us whether fields moved to a survivor.
  return mergeDisposition==='confirmed_standalone_delete'?'delete':'review_merge_or_delete';
}


// Pure preparation only. A caller must persist an explicitly accepted baseline,
// perform the conditional PUT, verify readback, then advance that baseline.


const fields = {
  name:['N','FN','NICKNAME'], notes:['NOTE'], emails:['EMAIL'],
  phoneNumbers:['TEL'], addresses:['ADR'], urls:['URL','X-SOCIALPROFILE'],
  organizations:['ORG','TITLE'], birthday:['BDAY'], ims:['IMPP'],
  relatedPeople:['X-ABRELATEDNAMES'], photos:['PHOTO']
};
function snapshot({sourceContactId,uid,existingVcard,contactData}) {
  if(typeof sourceContactId!=='string'||!sourceContactId)throw Error('Source identity required');
  // Validate identity and the entire source, including populated unsupported data.
  patchSharedFields({uid,existingVcard,contactData});
  const lines=existingVcard.replace(/\r\n[ \t]/g,'').split('\r\n');
  const key=l=>l.split(':')[0].split(';')[0].split('.').at(-1).toUpperCase();
  const group=l=>{const h=l.split(':')[0].split(';')[0];return h.includes('.')?h.split('.')[0]:null;};
  const result={version:1,sourceContactId,uid,fields:{}};
  for(const [field,keys] of Object.entries(fields)) {
    if(!Object.hasOwn(contactData,field)||contactData[field]==null)continue;
    const selected=lines.filter(l=>keys.includes(key(l)));
    const groups=new Set(selected.map(group).filter(Boolean));
    // Include grouped labels/metadata. Conservative representation changes may
    // cause a hold, but must never hide an independent target edit.
    const target=lines.filter(l=>keys.includes(key(l))||groups.has(group(l))).sort();
    const source=field==='organizations'?contactData[field].slice(0,1):contactData[field];
    result.fields[field]={source:hash(source),target:hash(target)};
  }
  return result;
}
function prepareSharedUpdate(input) {
  const {source,sourceContactId,uid,existingVcard,targetEtag,baseline}=input;
  if(!source||source.contactId!==sourceContactId)throw Error('Source identity mismatch');
  if(typeof targetEtag!=='string'||!/^"[^"\r\n]+"$/.test(targetEtag))throw Error('Strong target ETag required');
  const current=snapshot({sourceContactId,uid,existingVcard,contactData:source.contactData});
  const held=(status,conflicts=[])=>({status,conflicts,changed:false,writesApplied:false});
  if(!baseline)return held('needs_baseline');
  if(baseline.version!==1||baseline.uid!==uid||baseline.sourceContactId!==sourceContactId||!baseline.fields)throw Error('Baseline identity/version mismatch');
  const patch={},conflicts=[];
  for(const field of new Set([...Object.keys(current.fields),...Object.keys(baseline.fields)])) {
    const now=current.fields[field],old=baseline.fields[field];
    if(!now) {conflicts.push(field);continue;}
    if(!old){
      // This field was absent from the accepted source snapshot. Permit an
      // addition only when the fresh target has no corresponding property or
      // grouped metadata. The conditional PUT protects against intervening edits.
      if(field!=='photos'&&now.target===hash([])){patch[field]=source.contactData[field];continue;}
      conflicts.push(field);continue;
    }
    if(!['source','target'].every(k=>/^[a-f0-9]{64}$/.test(old[k]))) {conflicts.push(field);continue;}
    if(now.source===old.source)continue; // Independent iCloud changes are retained.
    if(field==='photos'||now.target!==old.target) {conflicts.push(field);continue;}
    patch[field]=source.contactData[field];
  }
  if(conflicts.length)return held('conflict',conflicts);
  const prepared=patchSharedFields({uid,existingVcard,contactData:patch});
  return {...prepared,status:prepared.changed?'prepared-only':'unchanged',writesApplied:false,
    targetEtag,sourceEtag:source.etag,eventId:input.eventId,updatedFields:Object.keys(patch)};
}




function advanceSharedBaseline({source,uid,baseline,updatedFields,before,actual,expected,targetEtag}){
  const canonical=card=>{if(typeof card!=='string')throw Error('Missing readback');return card.replace(/\r\n[ \t]/g,'').split(/\r?\n/).filter(l=>l&&!/^(REV|PRODID):/.test(l)).sort();};
  if(JSON.stringify(canonical(actual))!==JSON.stringify(canonical(expected)))throw Error('Readback drift; do not retry');
  if(!/^"[^"\r\n]+"$/.test(targetEtag||''))throw Error('Strong readback ETag required');
  if(!baseline||baseline.uid!==uid||baseline.sourceContactId!==source.contactId||baseline.version!==1)throw Error('Baseline identity mismatch');
  const current=snapshot({sourceContactId:source.contactId,uid,existingVcard:actual,contactData:source.contactData});
  const next=JSON.parse(JSON.stringify(baseline));
  if(!Array.isArray(updatedFields)||!updatedFields.length||new Set(updatedFields).size!==updatedFields.length)throw Error('Updated field list required');
  for(const key of updatedFields){
    if(key==='photos'||!current.fields[key])throw Error('Unverified field baseline');
    if(!baseline.fields[key]){
      // New field baselines require the actual pre-write card as evidence that
      // the target field was empty, in addition to successful exact readback.
      const prior=snapshot({sourceContactId:source.contactId,uid,existingVcard:before,contactData:source.contactData});
      if(prior.fields[key]?.target!==hash([]))throw Error('New field was not empty before write');
    }
    next.fields[key]=current.fields[key];
  }
  // Keep the prior baseline for independent target edits; accepting them here
  // could allow the next source edit to overwrite an unresolved local change.
  return {verified:true,targetEtag,baselineJson:JSON.stringify(next)};
}


// Lightweight evidence for shared-field writes. Caller must durably persist a
// receipt BEFORE PUT; this module neither writes nor retries a contact.



function cardDigest(card,uid){
 if(typeof card!=='string'||/\r(?!\n)|(?<!\r)\n/.test(card)||!card.endsWith('\r\n'))throw Error('Invalid readback format');
 const lines=card.replace(/\r\n[ \t]/g,'').split('\r\n').filter(Boolean);
 if(lines[0]!=='BEGIN:VCARD'||lines.at(-1)!=='END:VCARD'||lines.filter(x=>x==='BEGIN:VCARD').length!==1||lines.filter(x=>x==='END:VCARD').length!==1||lines.filter(x=>/^UID[;:]/i.test(x)).length!==1||!lines.includes('UID:'+uid)||!lines.includes('VERSION:3.0'))throw Error('Readback identity mismatch');
 return hash(lines.filter(x=>! /^(REV|PRODID):/.test(x)).sort());
}
function createSharedWriteReceipt(input){
 const prepared=prepareSharedUpdate(input);
 if(prepared.status!=='prepared-only'||!prepared.changed)throw Error('Prepared shared-field update required');
 if(typeof input.source.etag!=='string'||!input.source.etag||typeof input.eventId!=='string'||!input.eventId)throw Error('Source version and event identity required');
 const next=advanceSharedBaseline({source:input.source,uid:input.uid,baseline:input.baseline,updatedFields:prepared.updatedFields,before:input.existingVcard,actual:prepared.vcard,expected:prepared.vcard,targetEtag:input.targetEtag});
 return {version:1,operation:'shared_update',eventId:input.eventId,sourceContactId:input.sourceContactId,uid:input.uid,sourceEtag:input.source.etag,sourceHash:hash(input.source.contactData),beforeTargetEtag:input.targetEtag,beforeHash:cardDigest(input.existingVcard,input.uid),expectedHash:cardDigest(prepared.vcard,input.uid),baselineHash:hash(input.baseline),expectedBaselineJson:next.baselineJson};
}
function reconcileSharedWrite({receipt,eventId,sourceContactId,uid,source,baseline,statusCode,actual,targetEtag}){
 const hold=reason=>({status:'held',reason,writesAllowed:false});
 if(!receipt||receipt.version!==1||receipt.operation!=='shared_update'||receipt.eventId!==eventId||receipt.uid!==uid||receipt.sourceContactId!==sourceContactId)return hold('receipt_identity');
 if(!['sourceHash','beforeHash','expectedHash','baselineHash'].every(k=>/^[a-f0-9]{64}$/.test(receipt[k]||'')))return hold('invalid_receipt');
 if(statusCode!==200)return hold('readback_unavailable');
 if(!/^"[^"\r\n]+"$/.test(targetEtag||''))return hold('readback_version');
 let digest,next;try{digest=cardDigest(actual,uid);next=JSON.parse(receipt.expectedBaselineJson);}catch{return hold('invalid_readback_or_receipt');}
 if(!next||next.version!==1||next.uid!==uid||next.sourceContactId!==sourceContactId||!next.fields)return hold('receipt_baseline_identity');
 if(!baseline||hash(baseline)!==receipt.baselineHash)return hold('baseline_changed');
 if(digest===receipt.beforeHash)return hold('write_not_observed');
 if(digest!==receipt.expectedHash)return hold('readback_drift');
 if(targetEtag===receipt.beforeTargetEtag)return hold('write_version_not_observed');
 if(!source||source.contactId!==sourceContactId||source.etag!==receipt.sourceEtag||hash(source.contactData)!==receipt.sourceHash)return hold('source_changed');
 return {status:'verified_recovered',writesAllowed:false,baselineJson:receipt.expectedBaselineJson,targetEtag};
}


// Bundled after shared-fields.js, sync-state.js and prepare-shared-update.js.
// Malformed/unsupported source data is retained as a held event, not a write.
try {
  const source=readSourceResponse(input.source);
  const baseline=typeof input.baseline==='string'&&input.baseline?JSON.parse(input.baseline):input.baseline||null;
  const r=prepareSharedUpdate({...input,source,baseline});
  if(r.status==='prepared-only')r.writeReceiptJson=JSON.stringify(createSharedWriteReceipt({...input,source,baseline}));
  return {...r,eventState:r.status==='prepared-only'?'prepared_shared_fields':
    r.status==='unchanged'?'unchanged_shared_fields':
